import { mkdir, copyFile, readdir, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const here = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(here, '..');
const sourceScripts = path.join(root, 'engine', 'scripts');
const resourceScripts = path.join(root, 'src-tauri', 'resources', 'engine', 'scripts');
const iconsDir = path.join(root, 'src-tauri', 'icons');

await mkdir(resourceScripts, { recursive: true });
await mkdir(iconsDir, { recursive: true });

for (const entry of await readdir(sourceScripts, { withFileTypes: true })) {
  if (entry.isFile() && entry.name.toLowerCase().endsWith('.ps1')) {
    await copyFile(path.join(sourceScripts, entry.name), path.join(resourceScripts, entry.name));
  }
}

const icons = {
  '32x32.png': '',
  '128x128.png': '',
  '128x128@2x.png': ''
};

for (const [name, base64] of Object.entries(icons)) {
  await writeFile(path.join(iconsDir, name), Buffer.from(base64, 'base64'));
}

console.log('[NOVA] Bundle resources prepared.');
